#!/bin/bash
# Generated by gen.py from fabric.py: leaf1, leaf, AS 65101, VTEP 10.0.1.1.
set -euo pipefail
# Front-panel ports appear once syncd is up; then let the switch settle.
until ip link show Ethernet0 >/dev/null 2>&1; do sleep 1; done
until ip link show Ethernet4 >/dev/null 2>&1; do sleep 1; done
until ip link show Ethernet8 >/dev/null 2>&1; do sleep 1; done
until ip link show Ethernet12 >/dev/null 2>&1; do sleep 1; done
sleep 5
sysctl -qw net.ipv4.fib_multipath_hash_policy=1   # ECMP on the L4 hash, as on hardware
config loopback add Loopback0
config interface ip add Loopback0 10.0.1.1/32
config interface ip add Ethernet8 10.1.1.1/31
config interface startup Ethernet8
config interface ip add Ethernet12 10.1.2.1/31
config interface startup Ethernet12
config vxlan add vtep1 10.0.1.1
config vxlan evpn_nvo add nvo1 vtep1
# tenant red: L2 VNI 10010 on Vlan10, L3 VNI 10100 on Vlan101
config vrf add Vrf-red
config vlan add 10
config vlan member add -u 10 Ethernet0
config interface startup Ethernet0
config vxlan map add vtep1 10 10010
config neigh-suppress vlan 10 on
config vlan add 101
config vxlan map add vtep1 101 10100
config vrf add_vrf_vni_map Vrf-red 10100
config interface vrf bind Vlan10 Vrf-red
config interface ip add Vlan10 172.16.10.1/24
config interface vrf bind Vlan101 Vrf-red
# tenant blue: L2 VNI 20010 on Vlan20, L3 VNI 20100 on Vlan201
config vrf add Vrf-blue
config vlan add 20
config vlan member add -u 20 Ethernet4
config interface startup Ethernet4
config vxlan map add vtep1 20 20010
config neigh-suppress vlan 20 on
config vlan add 201
config vxlan map add vtep1 201 20100
config vrf add_vrf_vni_map Vrf-blue 20100
config interface vrf bind Vlan20 Vrf-blue
config interface ip add Vlan20 172.16.20.1/24
config interface vrf bind Vlan201 Vrf-blue
# FRR binds an L3 VNI only to a VRF the kernel already has.
until ip link show Vrf-red >/dev/null 2>&1; do sleep 1; done
until ip link show Vrf-blue >/dev/null 2>&1; do sleep 1; done
# docker-sonic-vs leaves bgpd stopped and has no bfdd program (it is
# frr_mgmt_framework-only), so start bgpd and run bfdd directly.
supervisorctl status bgpd | grep -q RUNNING || supervisorctl start bgpd
pgrep -x bfdd >/dev/null || /usr/lib/frr/bfdd -d -A 127.0.0.1
until vtysh -c 'show bfd peers' >/dev/null 2>&1; do sleep 1; done
vtysh -f /configs/frr.conf
touch /tmp/al-ready
